ST.xhtml:p:
IF bVar THEN
LocalVar1 := LREAL_TO_DINT(InputVar);
LocalVar2 := InputVar - DINT_TO_LREAL(LocalVar1);
LocalVar3 := MOD(LocalVar1,90);
LocalVar4 := LocalVar2 + DINT_TO_LREAL(LocalVar3);

IF LocalVar4 > 0.0 THEN
  LocalVar4 := LocalVar4 -90.0;
END_IF;  
FUN_FMOD := LocalVar4;

ELSE
LocalVar1 := LREAL_TO_DINT(InputVar);
LocalVar2 := InputVar - DINT_TO_LREAL(LocalVar1);
LocalVar3 := MOD(LocalVar1,360);
LocalVar4 := LocalVar2 + DINT_TO_LREAL(LocalVar3);

FUN_FMOD := LocalVar4;  

END_IF;
